import { fileURLToPath } from "node:url";

/**
 * Absolute path to the Drizzle migrations generated by `drizzle-kit`
 * (see `drizzle.sqlite.config.ts` -> `out: "./drizzle/sqlite/migrations"`).
 *
 * Exported so callers do not climb to it with a relative URL.
 */
export const migrationsFolder = fileURLToPath(
  new URL("../../drizzle/sqlite/migrations", import.meta.url),
);
